/*
* Servicio de comunicación con el backend
* Implementar funciones para:
* - Autenticación (login, registro, logout)
* - Gestión de partidas (crear, cargar, guardar)
* - Acciones del juego (movimiento, combate, gestión)
*/

import axios from 'axios';
import { authService } from './authService';

// Crear instancia de axios con URL base
const API = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8000/api',
});

// Interceptor para añadir token de autenticación
API.interceptors.request.use(
  (config) => {
    const token = authService.getToken();
    if (token) {
      config.headers['Authorization'] = `Bearer ${token}`;
    }
    
    // Asegurar que para POST requests usamos application/json
    if (config.method === 'post') {
      config.headers['Content-Type'] = 'application/json';
    }
    
    return config;
  },
  (error) => Promise.reject(error)
);

// Bandera para modo de desarrollo
const DEV_MODE = true; // Cambiar a false en producción

export const gameService = {
  createGame: async (config: any) => {
    console.log('Creating new game with config:', config);
    try {
      // Intentar crear la partida normalmente
      const response = await API.post('/games', { config });
      console.log('Game created successfully:', response.data);
      return response;
    } catch (error) {
      console.error('Error creating game:', error);
      
      // En modo desarrollo, simular una respuesta exitosa para continuar
      if (DEV_MODE) {
        console.warn('DEV MODE: Returning mock game response');
        
        // Esperar 1 segundo para simular latencia de red
        await new Promise(resolve => setTimeout(resolve, 1000));
        
        // Crear una respuesta simulada que se parece a la respuesta real
        return {
          data: {
            game_id: 'dev-game-' + Math.random().toString(36).substring(2, 9),
            game_state: {
              // Estado básico de juego simulado
              player: {
                heroes: [{
                  id: 'hero1',
                  name: 'Héroe 1',
                  position: { x: 5, y: 5 },
                  stats: {
                    attack: 5,
                    defense: 3,
                    movement_points: 20,
                    movement_points_left: 20
                  },
                  army: []
                }],
                cities: [{
                  id: 'city1',
                  name: 'Ciudad Central',
                  position: { x: 48, y: 48 },
                  buildings: [{
                    id: 'castle1',
                    name: 'Castillo Central',
                    position: { x: 48, y: 48 },
                    is_castle: true,
                    built: true,
                    can_recruit: true,
                    building_type: 'castle'
                  }]
                }],
                resources: { gold: 5000, wood: 30, stone: 30 }
              },
              ai: {
                heroes: [],
                cities: [],
                resources: { gold: 5000, wood: 30, stone: 30 }
              },
              map: {
                size: { width: 100, height: 100 },
                tiles: Array(100 * 100).fill({ terrain: 'grass', passable: true })
              },
              turn: 1,
              current_player: 'player'
            },
            message: 'Partida creada correctamente (simulado en modo desarrollo)'
          }
        };
      }
      
      // Si no estamos en modo desarrollo, rechazar el error
      throw error;
    }
  },
  
  loadGame: async (gameId: string) => {
    try {
      console.log(`Loading game ${gameId}`);
      const response = await API.get(`/games/${gameId}`);
      return response;
    } catch (error) {
      console.error('Error loading game:', error);
      
      // En modo desarrollo, proporcionar datos simulados
      if (DEV_MODE && gameId.startsWith('dev-game-')) {
        console.warn('DEV MODE: Returning mock game data');
        
        // Simular latencia
        await new Promise(resolve => setTimeout(resolve, 800));
        
        // Respuesta simulada similar a createGame
        return {
          data: {
            game_state: {
              // Mismo estado simulado que en createGame
              player: {
                heroes: [{
                  id: 'hero1',
                  name: 'Héroe 1',
                  position: { x: 5, y: 5 },
                  stats: {
                    attack: 5,
                    defense: 3,
                    movement_points: 20,
                    movement_points_left: 20
                  },
                  army: []
                }],
                cities: [{
                  id: 'city1',
                  name: 'Ciudad Central',
                  position: { x: 48, y: 48 },
                  buildings: [{
                    id: 'castle1',
                    name: 'Castillo Central',
                    position: { x: 48, y: 48 },
                    is_castle: true,
                    built: true,
                    can_recruit: true,
                    building_type: 'castle'
                  }]
                }],
                resources: { gold: 5000, wood: 30, stone: 30 }
              },
              ai: {
                heroes: [],
                cities: [],
                resources: { gold: 5000, wood: 30, stone: 30 }
              },
              map: {
                size: { width: 100, height: 100 },
                tiles: Array(100 * 100).fill({ terrain: 'grass', passable: true })
              },
              turn: 1,
              current_player: 'player'
            }
          }
        };
      }
      
      throw error;
    }
  },
  
  saveGame: async (gameId: string, gameState: any) => {
    return await API.put(`/games/${gameId}`, { game_state: gameState });
  },
  
  executeAction: async (gameId: string, action: any) => {
    try {
      console.log(`Executing action in game ${gameId}:`, action);
      const response = await API.post(`/games/${gameId}/action`, action);
      console.log('Action response:', response.data);
      
      // Si no tenemos estado del juego en la respuesta, recargarlo
      if (!response.data.game_state) {
        console.log('Game state not found in response, reloading...');
        const gameResponse = await API.get(`/games/${gameId}`);
        response.data.game_state = gameResponse.data.game_state;
        console.log('Reloaded game state:', response.data.game_state);
      }
      
      return response;
    } catch (error) {
      console.error('Action error:', error);
      throw error;
    }
  },
  
  listGames: async () => {
    return await API.get('/games');
  },
  
  deleteGame: async (gameId: string) => {
    return await API.delete(`/games/${gameId}`);
  },

  getSavedGames: async () => {
    try {
      return await API.get('/games');
    } catch (error) {
      console.error('Error getting saved games:', error);
      
      if (DEV_MODE) {
        console.warn('DEV MODE: Returning mock saved games');
        return {
          data: [
            { id: 'dev-game-1', name: 'Partida de desarrollo 1', created_at: new Date().toISOString() },
            { id: 'dev-game-2', name: 'Partida de desarrollo 2', created_at: new Date().toISOString() }
          ]
        };
      }
      
      throw error;
    }
  },
  
  getScenarios: async () => {
    try {
      return await API.get('/scenarios');
    } catch (error) {
      console.error('Error getting scenarios:', error);
      
      if (DEV_MODE) {
        console.warn('DEV MODE: Returning mock scenarios');
        return {
          data: [
            { id: '6803955d975eb43e3e182cbb', name: 'Escenario básico', description: 'Mapa de inicio para aprender a jugar' },
            { id: 'scenario-2', name: 'Batalla épica', description: 'Enfrenta grandes desafíos en este escenario' }
          ]
        };
      }
      
      throw error;
    }
  },
  
  buildBuilding: async (gameId: string, cityId: string, buildingId: string) => {
    return await API.post(`/games/${gameId}/action`, {
      type: "buildStructure",
      details: {
        cityId,
        buildingId
      }
    });
  },
  
  recruitUnits: async (gameId: string, cityId: string, unitId: string, amount: number, heroId?: string) => {
    return await API.post(`/games/${gameId}/action`, {
      type: "recruitUnits",
      details: {
        cityId,
        unitId,
        amount,
        heroId
      }
    });
  }
};

export { authService };  // Re-exportar authService para mantener compatibilidad

export default API;
